interface Display {
    void display();
}

class DisplayImpl implements Display {
    @Override
    public void display() {
        System.out.println("Hello from DisplayImpl.");
    }
}

public class Main {
    public static void main(String[] args) {
        Display displayRef = new DisplayImpl();
        displayRef.display();
    }
}

interface Display {
    void display();
}

class Launch {
    class DisplayImpl implements Display {
        @Override
        public void display() {
            System.out.println("Hello from inner class.");
        }
    }

    public static void main(String[] args) {
        Launch launch = new Launch();
        Display displayRef = launch.new DisplayImpl();
        displayRef.display();
    }
}

interface Display {
    void display();
}

public class Main {
    public static void main(String[] args) {
        Display displayRef = new Display() {
            @Override
            public void display() {
                System.out.println("Hello from anonymous class.");
            }
        };

        displayRef.display();
    }
}

A lambda expression uses a parameter list, the arrow operator, and an expression or block containing the implementation.

Example:
() -> { System.out.println("Hello"); }

